import heapq


def topo_sort(graph: dict[str, list[str]]) -> list[str]:
    successors: dict[str, set[str]] = {}
    for source, targets in graph.items():
        successors.setdefault(source, set()).update(targets)
        for target in targets:
            successors.setdefault(target, set())

    indegree: dict[str, int] = {vertex: 0 for vertex in successors}
    for targets in successors.values():
        for target in targets:
            indegree[target] += 1

    heap = [vertex for vertex, degree in indegree.items() if degree == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        vertex = heapq.heappop(heap)
        result.append(vertex)
        for target in successors[vertex]:
            indegree[target] -= 1
            if indegree[target] == 0:
                heapq.heappush(heap, target)

    if len(result) != len(successors):
        raise ValueError("graph contains a cycle")
    return result
